<?php
/**
 * Plugin Name: Tags 2 Go Advertising Landing Page Embedded
 * Description: Publishes the approved advertising landing page at its stable URL with self-contained assets.
 * Version: 1.0.3
 * Author: DM Marketing Specialist
 */

if (!defined('ABSPATH')) { exit; }

function tags2go_landing_v103_ensure_page(): void
{
    if (get_page_by_path('philadelphia-title-registration-services', OBJECT, 'page') instanceof WP_Post) { return; }
    wp_insert_post([
        'post_title' => 'Philadelphia Title and Registration Services',
        'post_name' => 'philadelphia-title-registration-services',
        'post_status' => 'publish',
        'post_type' => 'page',
        'post_content' => '',
        'comment_status' => 'closed',
    ]);
    flush_rewrite_rules(false);
}
register_activation_hook(__FILE__, 'tags2go_landing_v103_ensure_page');

function tags2go_landing_v103_render(): void
{
    if (!is_page('philadelphia-title-registration-services')) { return; }
    status_header(200);
    header('Content-Type: text/html; charset=UTF-8');
    header('Cache-Control: public, max-age=300');
    echo base64_decode('');
    exit;
}
add_action('template_redirect', 'tags2go_landing_v103_render', 0);
